// The Gujarati patient summary (Phase 10 Run 1, ADR-D41). Input: the SIGNED visit snapshot only (never the raw transcript) plus
// two doctor-typed free-text fields. Output: four template variables, the Gujarati text as the patient would see it, and an
// approximate English back-translation. Nothing here is generated by a model: facts and medicine fields are copied VERBATIM
// from the snapshot, labels and frequency words come from the fixed phrase table, warning signs and follow-up are exactly what
// the doctor typed (whitespace collapsed, because a template variable must be one line).
import { createHash } from 'node:crypto';
import type { SignedContent, SignedFact, SignedMedicine } from '../visits/repository.js';
import {
  FACT_LABEL,
  FREQUENCY,
  P,
  PHRASE_TABLE_VERSION,
  TEMPLATE_BODY_EN,
  TEMPLATE_BODY_GU,
} from './phrases.js';

export const MAX_PARAM_CHARS = 900;
export const MAX_FREE_TEXT_CHARS = 600;
export const ITEM_SEPARATOR = ' | ';

export interface SummaryParams {
  /** {{1}} findings, {{2}} medicines, {{3}} warning signs, {{4}} follow-up: each ONE line */
  p1: string;
  p2: string;
  p3: string;
  p4: string;
}
export interface FreeText {
  warningSigns: string;
  followUp: string;
}
export interface Summary {
  params: SummaryParams;
  textGu: string;
  textEn: string;
  phraseTableVersion: string;
}

export class SummaryError extends Error {
  constructor(
    public readonly code: 'too_long' | 'bad_text',
    message: string,
  ) {
    super(message);
    this.name = 'SummaryError';
  }
}

/** A template variable is one line: newlines and tabs become one space; more than one space in a row becomes one. */
export const oneLine = (s: string): string => s.replace(/\s+/g, ' ').trim();

export const medicineHead = (m: SignedMedicine): string =>
  [m.name, m.strength, m.doseForm].filter(Boolean).join(' ');

/** The tail of a medicine line: dose, the frequency phrase (Gujarati), duration, note, in this order. */
export const medicineTail = (m: SignedMedicine, lang: 'gu' | 'en'): string =>
  [m.dose, FREQUENCY[m.frequency]?.[lang] ?? m.frequency, m.duration, m.note]
    .filter(Boolean)
    .join(', ');

function itemOf(n: number, m: SignedMedicine, lang: 'gu' | 'en'): string {
  return `${n}. ${medicineHead(m)} - ${medicineTail(m, lang)}`;
}

/** Facts that go to the patient: the doctor-confirmed ones in the snapshot, except a red-flag mention (ADR-D41). */
export function patientFacts(content: SignedContent): SignedFact[] {
  return content.facts.filter((f) => f.type in FACT_LABEL);
}

function factItem(f: SignedFact, lang: 'gu' | 'en'): string {
  const label = FACT_LABEL[f.type]?.[lang] ?? f.type;
  const flags = [f.negated ? P.negated[lang] : null, f.uncertain ? P.uncertain[lang] : null].filter(
    Boolean,
  );
  return `${label}: ${f.value}${flags.length > 0 ? ` (${flags.join(', ')})` : ''}`;
}

const fill = (template: string, p: SummaryParams): string =>
  template
    .replace('{{1}}', p.p1)
    .replace('{{2}}', p.p2)
    .replace('{{3}}', p.p3)
    .replace('{{4}}', p.p4);

export function buildSummary(content: SignedContent, free: FreeText): Summary {
  const warning = oneLine(free.warningSigns);
  const follow = oneLine(free.followUp);
  if (warning.length > MAX_FREE_TEXT_CHARS || follow.length > MAX_FREE_TEXT_CHARS) {
    throw new SummaryError(
      'too_long',
      'The warning signs and the follow-up must each be at most 600 characters.',
    );
  }
  for (const text of [warning, follow]) {
    if (/\{\{\s*\d+\s*\}\}/.test(text)) {
      throw new SummaryError('bad_text', 'The text must not contain {{ }} placeholders.');
    }
  }
  const facts = patientFacts(content);
  const bad = [
    ...facts.map((f) => f.value),
    ...content.medicines.flatMap((m) => [m.name, medicineHead(m), medicineTail(m, 'gu')]),
  ];
  if (bad.some((s) => s.includes(ITEM_SEPARATOR) || /[\r\n\t]/.test(s) || /\{\{/.test(s))) {
    throw new SummaryError(
      'bad_text',
      'A fact or a medicine contains a line break or the separator " | " and cannot be sent as it is. Amend the visit.',
    );
  }
  const build = (lang: 'gu' | 'en'): SummaryParams => ({
    p1: facts.length > 0 ? facts.map((f) => factItem(f, lang)).join(ITEM_SEPARATOR) : P.none[lang],
    p2:
      content.medicines.length > 0
        ? content.medicines.map((m, i) => itemOf(i + 1, m, lang)).join(ITEM_SEPARATOR)
        : P.none[lang],
    p3: warning || P.none[lang],
    p4: follow || P.none[lang],
  });
  const gu = build('gu');
  const en = build('en');
  // the doctor's own words are the same on both sides
  en.p3 = gu.p3 === P.none.gu ? P.none.en : gu.p3;
  en.p4 = gu.p4 === P.none.gu ? P.none.en : gu.p4;
  for (const [k, v] of Object.entries(gu)) {
    if (v.length > MAX_PARAM_CHARS) {
      throw new SummaryError(
        'too_long',
        `The summary is too long to send (${k}). Shorten the text.`,
      );
    }
  }
  return {
    params: gu,
    textGu: fill(TEMPLATE_BODY_GU, gu),
    textEn: fill(TEMPLATE_BODY_EN, en),
    phraseTableVersion: PHRASE_TABLE_VERSION,
  };
}

/** SHA-256 over the exact text and the exact variables that are approved and sent. */
export const summaryHash = (textGu: string, params: SummaryParams): string =>
  createHash('sha256')
    .update(
      JSON.stringify({ textGu, params: [params.p1, params.p2, params.p3, params.p4] }),
      'utf8',
    )
    .digest('hex');
